<template><div class="page"><div class="welcome"><div><p>{{greeting}}，{{user.realName||'管理员'}} 👋</p><h1>今天也一起打造更好的阅读体验</h1></div><div class="date"><el-icon><Calendar/></el-icon>{{today}}</div></div><div class="metric-grid"><div class="metric" v-for="m in metrics" :key="m.label" :style="{'--glow':m.glow}"><div class="metric-label">{{m.label}}</div><div class="metric-value">{{m.value}}</div><div class="metric-note">{{m.note}}</div></div></div><div class="charts"><el-card class="chart-card"><template #header><b>近7天借阅趋势</b></template><div ref="trendEl" class="chart"></div></el-card><el-card class="chart-card"><template #header><b>图书分类分布</b></template><div ref="pieEl" class="chart"></div></el-card></div><div class="bottom"><el-card><template #header><div class="card-head"><b>热门图书排行</b><el-button text type="primary" @click="$router.push('/books')">查看全部</el-button></div></template><div class="rank" v-for="(b,i) in data.hotBooks||[]" :key="b.title"><strong :class="{top:i<3}">{{i+1}}</strong><div><b>{{b.title}}</b><small>累计借阅 {{b.value}} 次</small></div><el-progress :percentage="Math.min(100,b.value)" :show-text="false"/></div></el-card><el-card><template #header><b>系统动态</b></template><el-timeline><el-timeline-item timestamp="刚刚" type="success">图书服务运行正常</el-timeline-item><el-timeline-item timestamp="10分钟前" type="primary">读者完成图书归还</el-timeline-item><el-timeline-item timestamp="今天 09:32">管理员更新借阅规则</el-timeline-item><el-timeline-item timestamp="昨天 16:20">新增馆藏图书 6 本</el-timeline-item></el-timeline></el-card></div></div></template>
<script setup lang="ts">import{ref,onMounted,nextTick}from'vue';import*as echarts from'echarts';import api from'../api';const user=JSON.parse(localStorage.getItem('user')||'{}'),now=new Date(),today=now.toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'}),greeting=now.getHours()<12?'早上好':now.getHours()<18?'下午好':'晚上好';const data=ref<any>({}),metrics=ref<any[]>([]),trendEl=ref(),pieEl=ref();onMounted(async()=>{data.value=await api.get('/api/statistics/dashboard');metrics.value=[{label:'馆藏图书',value:data.value.bookCount||0,note:`共 ${data.value.copyCount||0} 册馆藏`,glow:'#e3f4ef'},{label:'当前借出',value:data.value.borrowedCount||0,note:'实时借阅状态',glow:'#e4effe'},{label:'注册读者',value:data.value.readerCount||0,note:'读者档案正常',glow:'#f8eddd'},{label:'逾期未还',value:data.value.overdueCount||0,note:'需要及时处理',glow:'#fde7e8'}];nextTick(draw)});function draw(){const trend=echarts.init(trendEl.value);trend.setOption({grid:{left:35,right:18,top:20,bottom:28},tooltip:{trigger:'axis'},xAxis:{type:'category',data:(data.value.borrowTrend||[]).map((x:any)=>x.label),axisLine:{show:false},axisTick:{show:false}},yAxis:{type:'value',splitLine:{lineStyle:{color:'#edf2f6'}}},series:[{type:'line',smooth:true,data:(data.value.borrowTrend||[]).map((x:any)=>x.value),symbolSize:8,lineStyle:{color:'#2ba67e',width:3},itemStyle:{color:'#2ba67e'},areaStyle:{color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:'rgba(43,166,126,.32)'},{offset:1,color:'rgba(43,166,126,0)'}])}}]});echarts.init(pieEl.value).setOption({tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['48%','70%'],center:['50%','43%'],label:{show:false},itemStyle:{borderRadius:7,borderColor:'#fff',borderWidth:3},data:data.value.categoryData||[]}],color:['#2ba67e','#4b8de8','#f4a64b','#8c70d8','#ef707a']})}</script>
<style scoped>.welcome{background:linear-gradient(120deg,#edf9f4,#f5fbff);border:1px solid #e4f1ed;border-radius:18px;padding:24px 28px;margin-bottom:18px;display:flex;justify-content:space-between;align-items:center}.welcome p{margin:0 0 6px;color:#258e6e;font-weight:700}.welcome h1{font-size:21px;margin:0}.date{color:#6f8092;font-size:13px;display:flex;gap:8px}.chart{height:280px}.bottom{display:grid;grid-template-columns:1.4fr 1fr;gap:18px;margin-top:18px}.card-head{display:flex;justify-content:space-between}.rank{display:grid;grid-template-columns:35px 1fr 150px;gap:12px;align-items:center;padding:10px 0}.rank strong{width:25px;height:25px;border-radius:8px;background:#edf1f5;display:grid;place-items:center;font-size:12px}.rank strong.top{background:#dff5ec;color:#218b69}.rank small{display:block;color:#99a4b2;font-size:11px;margin-top:4px}@media(max-width:900px){.bottom{grid-template-columns:1fr}}</style>

